    Library(const std::string& name, const std::vector<Book>& books)
        : name(name), books(books) {}

    void showBooks() const {
        std::cout << "Books available in " << name << " Library:" << std::endl;
        for (const auto& book : books) {
            std::cout << "- " << book.getTitle() << " by " << book.getAuthor() << std::endl;
        }
    }
};

