    Book b1("Clean Code", "Robert Martin");
    Book b2("The Pragmatic Programmer", "Andrew Hunt");
    std::vector<Book> bookList = {b1, b2};

    Library cityLibrary("City Library", bookList);
    cityLibrary.showBooks();
    return 0;
}

