        Classroom classroom(classroomName);
        classrooms.push_back(classroom);
        return classroom;
    }

    void leaveClassroom(const Classroom& classroom) {
        classrooms.erase(
            std::remove_if(classrooms.begin(), classrooms.end(),
                [&](const Classroom& c) { return c.getName() == classroom.getName(); }),
            classrooms.end());
    }

    std::string getName() const { return name; }
    int classroomCount() const { return static_cast<int>(classrooms.size()); }
};

