    Subject physics("Physics", msSmith, 4);
    Subject chemistry("Chemistry", msSmith, 3);
    Subject english("English", mrJohn, 4);

    // Add all subjects to the master school
    School school;
    school.addSubject(math);
    school.addSubject(physics);
    school.addSubject(chemistry);
    school.addSubject(english);

    // Student enrolls in classrooms and adds subjects
    Student alice("Alice");
    Classroom& classA = alice.enrollClassroom("Class A");
    Classroom& classB = alice.enrollClassroom("Class B");

    // Same subjects shared across classrooms
    classA.addSubject(math);
    classA.addSubject(physics);
    classA.addSubject(english);

    classB.addSubject(english);
    classB.addSubject(chemistry);

    std::cout << "School has " << school.getSubjectCount() << " subjects" << std::endl;
    std::cout << std::endl;

    std::cout << classA.getName() << " (" << classA.getSubjectCount()
               << " subjects, " << classA.getTotalHours() << " hrs/week):" << std::endl;
    for (const auto& s : classA.getSubjects()) {
        std::cout << "  - " << s.toString() << std::endl;
    }
    std::cout << std::endl;

    std::cout << classB.getName() << " (" << classB.getSubjectCount()
               << " subjects, " << classB.getTotalHours() << " hrs/week):" << std::endl;
    for (const auto& s : classB.getSubjects()) {
        std::cout << "  - " << s.toString() << std::endl;
    }
    std::cout << std::endl;

    std::cout << "After removing Class A:" << std::endl;
    std::cout << "  School still has " << school.getSubjectCount() << " subjects" << std::endl;
    std::cout << "  Class B still has " << classB.getSubjectCount() << " subjects" << std::endl;
    std::cout << "  Mathematics still exists: " << math.getTitle() << std::endl;
    return 0;
}
